import { motion } from 'framer-motion';
import { ChevronDown, ChevronUp } from 'lucide-react';

interface ShowMoreButtonProps {
  showAll: boolean;
  onClick: () => void;
}

export default function ShowMoreButton({ showAll, onClick }: ShowMoreButtonProps) {
  return (
    <motion.button
      whileHover={{ scale: 1.05 }}
      whileTap={{ scale: 0.95 }}
      onClick={onClick}
      className="inline-flex items-center gap-2 px-4 py-2 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light rounded-full hover:bg-primary/20 dark:hover:bg-primary/30 transition-colors text-sm font-medium"
    >
      {showAll ? (
        <>
          Show Less
          <ChevronUp className="w-4 h-4" />
        </>
      ) : (
        <>
          Show More
          <ChevronDown className="w-4 h-4" />
        </>
      )}
    </motion.button>
  );
}
